package com.bank.batch;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ReceiptDemo {

    private static final Logger log = Logger.getLogger(ReceiptDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ReceiptPrinter printer = new ReceiptPrinter();
        int n = 5;

        log.info("Printing receipts 1 to " + n + " (ascending):");
        printer.printAscending(1, n);

        log.info("Printing pending steps " + n + " to 1 (descending):");
        printer.printDescending(n);
    }
}

// ─── Would be in service/ReceiptPrinter.java in a real project ───
class ReceiptPrinter {

    private static final Logger log = Logger.getLogger(ReceiptPrinter.class.getName());

    // Ascending: print the current number, then recurse with current+1.
    void printAscending(int current, int n) {
        if (current > n) {            // BASE CASE: passed N, stop.
            return;
        }
        final int value = current;
        log.info(() -> "Receipt #" + value);
        printAscending(current + 1, n); // RECURSIVE CASE
    }

    // Descending: print first, then recurse with n-1 (matches the hint).
    void printDescending(int n) {
        if (n == 0) {                 // BASE CASE: reached zero, stop.
            return;
        }
        final int value = n;
        log.info(() -> "Step #" + value);
        printDescending(n - 1);        // RECURSIVE CASE
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
